local filesystem=require("filesystem");local shell=require("shell");local computer=require("computer");local config=require("config.config");local M={}
local files={"main.lua","config/config.lua","lib/utils.lua","modules/chat.lua","modules/flux.lua","modules/gui.lua","modules/me.lua","modules/resources.lua","modules/players.lua","modules/reactors.lua","modules/coolant_monitor.lua","modules/updater.lua"}
local function ensure(p)local d=p:match("^(.*)/[^/]+$");if d and not filesystem.exists(d)then filesystem.makeDirectory(d)end end
local function read(p)local f=io.open(p,"rb");if not f then return nil end;local b=f:read("*a");f:close();return b end
function M.run() local n=math.floor((tonumber(computer.uptime())or 0)*1000);local changed=0;for i,r in ipairs(files)do local live="/home/"..r;local tmp="/home/update_"..i;local url=config.githubBase..r.."?cb="..(n+i);local ok=shell.execute("wget -fq '"..url.."' '"..tmp.."'");if not ok or not filesystem.exists(tmp)or #(read(tmp)or"")<20 then return false,"Ошибка загрузки: "..r end;if read(live)~=read(tmp)then ensure(live);if filesystem.exists(live)then filesystem.remove(live)end;filesystem.rename(tmp,live);changed=changed+1 else filesystem.remove(tmp)end end;return true,"Обновление успешно. Обновлено файлов: "..changed end
return M
